import {dayKey,plusDays,initialState,eraseProgress,award,stats,enroll,grade,dueCards,validateTrack,validateBackup} from './core.mjs';
import {ankiRequest} from './anki.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arrow='<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M6 18 18 6M6 6h12v12"/></svg>';
const btn=(text,act,cls='secondary',extra='')=>`<button class="${cls}" data-action="${act}" ${extra}>${text.replace(/↗/g,arrow)}</button>`;
const badge=(text,cls='')=>`<span class="tag ${cls}">${esc(text)}</span>`;
let config,state,view='today',query='',filter='all',selectedTrack=null,reviewSelection=null,reviewAnswer=false,ankiKey='',ankiConnected=false,ankiDecks=[],ankiModels=[],ankiStatus='Not connected',toastTimeout;
const chosen=new Set();let audioContext;
let timer={mode:'focus',remaining:1500,total:1500,running:false,end:0,goal:'',cycle:0,id:null};
try{state=JSON.parse(localStorage.getItem('recall-forge:v1'))||initialState();validateBackup(state);state={...initialState(),...state,settings:{...initialState().settings,...state.settings}};const t=JSON.parse(localStorage.getItem('recall-forge:timer'));if(t)timer={...timer,...t};}catch{state=initialState();}
function save(){try{localStorage.setItem('recall-forge:v1',JSON.stringify(state));}catch{toast('Storage is full or unavailable. Export a backup now; recent changes are only in this tab.');}updateProfile();}
function saveTimer(){try{localStorage.setItem('recall-forge:timer',JSON.stringify(timer));}catch{}}
function toast(msg){clearTimeout(toastTimeout);$('#toast').textContent=msg;$('#toast').classList.add('show');toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function dialog(title,body,actions=''){const m=$('#modal');$('#modalContent').innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2>${btn('×','close','', 'aria-label="Close dialog"')}</div><div class="dialog-body">${body}</div><div class="dialog-actions">${actions}</div>`;if(!m.open)m.showModal();}
function close(){$('#modal').close();}
function download(name,data,type='application/json'){const u=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function eraseProgressDialog(){dialog('Erase learning progress?',`<p>This returns the plan to Day 1 and clears completed days and lessons, XP, levels, streaks, R/A/G assessments, scheduled reviews, review history and focus-session history. Any running timer stops.</p><p>Your custom tracks, flashcards, notes, tasks and preferences are kept. This affects this browser only; Anki decks and other devices are unchanged.</p><p>A backup download starts before progress is erased. Keep the downloaded JSON file to recover through Settings → Restore backup.</p>`,btn('Cancel','close','secondary','id="cancelErase"')+btn('Download backup & erase progress','confirm-erase-progress','danger'));$('#cancelErase').focus();}
function confirmEraseProgress(){const next=eraseProgress(state);download('Recall_Forge_Before_Erase_'+dayKey()+'.json',JSON.stringify(state,null,2));localStorage.removeItem('recall-forge:timer');localStorage.setItem('recall-forge:v1',JSON.stringify(next));state=next;timer={mode:'focus',remaining:state.settings.focus*60,total:state.settings.focus*60,running:false,end:0,goal:'',cycle:0,id:null};saveTimer();chosen.clear();reviewSelection=null;reviewAnswer=false;selectedTrack=null;delete window.pendingBackup;rebuildMap();close();navigate('settings');toast('Learning progress erased. Your study content and preferences are kept.');}
function celebrate(text){toast(text);playSound();if(state.settings.reducedMotion||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const host=$('#celebration');host.innerHTML=Array.from({length:24},(_,i)=>`<i style="--x:${Math.cos(i)*220}px;--y:${Math.sin(i)*160+140}px;--rot:${i*27}deg;background:${['#a4c57a','#e4ba78','#91b9ac'][i%3]}"></i>`).join('');setTimeout(()=>host.replaceChildren(),1200);}
async function playSound(){if(!state.settings.sound)return;try{if(state.settings.customAudio){const a=new Audio(state.settings.customAudio);a.volume=state.settings.volume;await a.play();return;}audioContext ||= new(window.AudioContext||window.webkitAudioContext)();await audioContext.resume();const now=audioContext.currentTime;[659.25,880,1318.5].forEach((freq,i)=>{const o=audioContext.createOscillator(),g=audioContext.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(0,now+i*.09);g.gain.linearRampToValueAtTime(state.settings.volume*.26,now+i*.09+.014);g.gain.exponentialRampToValueAtTime(.001,now+i*.09+.48);o.connect(g);g.connect(audioContext.destination);o.start(now+i*.09);o.stop(now+i*.09+.5);});}catch{toast('Sound was blocked. Tap Test sound to enable audio for this browser.');}}
function updateProfile(){const s=stats(state);$('#dueBadge').textContent=dueCards(state).length||'';$('#profileName').textContent=state.settings.name;$('#profileLevel').textContent=`Level ${s.level} · ${s.level>5?'Practitioner':'Explorer'}`;$('#soundToggle').textContent=state.settings.sound?'♫':'♪';$('#soundToggle').setAttribute('aria-pressed',String(state.settings.sound));document.body.classList.toggle('dark',state.settings.theme==='dark');document.body.classList.toggle('reduced',state.settings.reducedMotion);}
const day=()=>config.days[state.currentDay-1];
const tracks=()=>[...config.tracks,...state.customTracks];
const questions=()=>config.days.flatMap(d=>d.questions.map(q=>({...q,day:d.day,title:d.title,problem:d.meta.name}))).concat(state.customCards);
let questionMap;
function rebuildMap(){questionMap=new Map(questions().map(q=>[q.id,q]));}
function taskState(d=state.currentDay){return state.tasks[d]||{};}
function nav(){const entries=[['today','◫','Today'],['plan','▦','154-day plan'],['tracks','◈','Learning tracks'],['reviews','↻','Spaced repetition'],['bank','☷','Interview practice'],['flows','⤳','Request flows'],['notes','▤','Notes & tasks'],['analytics','▥','Progress'],['settings','⚙','Settings']];$('#nav').innerHTML=entries.map(([id,icon,label])=>`<button data-action="nav" data-view="${id}" class="${view===id?'active':''}"><span class="nav-icon">${icon}</span>${label}${id==='reviews'?`<span class="nav-pill">${dueCards(state).length}</span>`:''}</button>`).join('');$('#pageCrumb').textContent=entries.find(x=>x[0]===view)?.[2]||'Study method';}
function heading(title,sub,action=''){return `<div class="page-heading"><div><div class="eyebrow">YOUR PERSONAL LEARNING WORKSPACE</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
function render(){nav();updateProfile();const renderers={today:todayView,plan:planView,tracks:tracksView,reviews:reviewsView,bank:bankView,flows:flowsView,notes:notesView,analytics:analyticsView,settings:settingsView,method:methodView};$('#main').innerHTML=(renderers[view]||todayView)();updateTimer();}
function navigate(v){view=v;query='';filter='all';selectedTrack=null;reviewSelection=null;history.replaceState(null,'','#'+v);document.body.classList.remove('nav-open');render();window.scrollTo({top:0,behavior:'instant'});}
function statCard(label,value,foot,progress=null){return `<div class="stat"><div class="stat-label">${label}<span>${arrow}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div>${progress!==null?`<div class="progress"><span style="width:${Math.min(100,progress)}%"></span></div>`:''}</div>`;}
function todayView(){const d=day(),s=stats(state),due=dueCards(state),tasks=taskState(),done=Object.values(tasks).filter(Boolean).length;const reviewToday=state.reviewLog.filter(x=>x.date===dayKey()).length;return `${heading('Make it stick.',`A little progress today. A stronger engineer tomorrow.`, `<div class="heading-streak"><span class="fire">♨</span><div><b>${s.streak}-day streak</b><small>${s.streak?'Keep showing up.':'Your next session starts it.'}</small></div></div>`)}<div class="stats-grid">${statCard('PREPARATION PROGRESS',`${Math.round(s.completed/154*100)}<span>%</span>`,`<b>${s.completed}</b> of 154 days complete`,s.completed/154*100)}${statCard('REVIEWS DUE',`${due.length}<span> cards</span>`,due.length?'<b>Weak items first</b> · two-card daily cap':'Your review queue is clear')}${statCard('INDEPENDENT APPLICATION',`${s.applied}<span> proofs</span>`,`${s.recall} concepts recalled without notes`)}${statCard('LEARNING XP',`${s.xp}<span> XP</span>`,`Level ${s.level} · ${200-s.xp%200} XP to next level`,s.xp%200/2)}</div><div class="dashboard-grid"><div><section class="hero"><div><div class="eyebrow">DAY ${String(d.day).padStart(3,'0')} / 154 &nbsp; · &nbsp; WEEK ${d.week}</div><h2>${esc(d.title)}</h2><p>${esc(d.focus)}</p>${btn('Continue today’s practice <span>↗</span>','task-backend','primary')}</div><div class="hero-art"><div class="orb"><span>✳</span></div></div></section><div class="section-heading"><h2>Your daily mission</h2><small>${done}/3 blocks attempted · ${d.minutes} min</small></div><div class="mission-list">${mission('backend',d.weekday==='Saturday'?'Build one runnable increment':d.weekday==='Sunday'?'Weekly assessment':d.title,d.budget[0],d.weekday==='Sunday'?'Five prompts, closed notes':d.backend,'{}','')}${mission('dsa',d.weekday==='Sunday'?'Plan the next week':d.meta.name,d.budget[1],d.weekday==='Sunday'?'Pick one carry-over and a realistic retry date':`${d.meta.difficulty} · ${d.meta.pattern}`,'⌘','blue')}${mission('review','Protected spaced repetition',20,`${Math.min(2,due.length)} due cards · recall → check → correct`,'↻','purple')}</div><div class="section-heading"><h2>Keep it in memory</h2>${btn('Open review queue →','nav','quiet','data-view="reviews"')}</div><div class="review-preview">${due.length?due.slice(0,2).map(r=>{const q=questionMap.get(r.id);return `<div class="review-mini">${badge(r.guided?'RETRY · GUIDED':'DUE FOR RECALL',r.guided?'amber':'mint')}<p>${esc(q?.question||r.id)}</p>${btn('Recall without notes →','open-review','quiet',`data-id="${esc(r.id)}"`)}</div>`;}).join(''):`<div class="review-mini">${badge('BUILD YOUR REVIEW QUEUE','mint')}<p>Complete a backend or DSA block to schedule its first recall card.</p><span class="muted">+1 · +3 · +7 · +14 · +30 days</span></div><div class="review-mini">${badge('TODAY’S COLD PROMPT')}<p>${esc(d.questions[0].question)}</p>${btn('Try active recall →','practice','quiet',`data-id="${d.questions[0].id}"`)}</div>`}</div><div class="hint-row"><span>${reviewToday}/2 cards reviewed today · 20 minutes protected</span><span>R ≠ A</span></div><div class="section-heading"><h2>Left over from today</h2><small>Carry one clear next action.</small></div><textarea id="leftover" placeholder="Exact blocker → next action → retry date" data-note="leftover-${d.day}">${esc(state.notes['leftover-'+d.day]||'')}</textarea><div class="hint-row"><span>Saved as you type</span>${btn('View the full plan →','nav','quiet','data-view="plan"')}</div></div><aside class="dashboard-right">${timerPanel()}<div class="right-note"><b>◌ Recall first. Reveal second.</b><p>Say it aloud or write it from memory. A correct explanation earns R. An independent implementation or diagnosis earns A.</p>${btn('The study method ↗','nav','quiet','data-view="method"')}</div><div class="panel" style="margin-top:16px"><div class="panel-head"><h3>One intention</h3><span>✦</span></div><p class="muted" style="font-size:11px;margin:12px 0">What will you be able to demonstrate when this session ends?</p><input class="input-subtle" data-note="intention" placeholder="e.g. Trace a collision without notes" value="${esc(state.notes.intention||'')}"><p class="timer-note">Phone away · notifications off · one task</p></div></aside></div>`;}
function mission(key,title,min,desc,icon,cls){const done=taskState()[key];return `<div class="mission ${done?'completed':''}"><div class="task-icon ${cls}">${icon}</div><div class="mission-info"><h3>${esc(title)}</h3><p>${esc(desc)}</p><div class="task-meta"><span>◷ ${min} MIN</span><span class="green">${key==='review'?'RETENTION':key==='dsa'?'DELIBERATE PRACTICE':'LEARN + DEMONSTRATE'}</span></div></div>${btn(done?'✓':'','task-'+key,'circle-check '+(done?'done':''),`aria-label="${done?'View':'Open'} ${key} block"`)}</div>`;}
function timerPanel(){return `<div class="panel timer-panel"><div class="panel-head"><h3>◷ Focus room</h3><span>Pomodoro</span></div><div class="timer-tabs">${['focus','short','long'].map((m,i)=>btn(['Focus','Short break','Long break'][i],'timer-mode',timer.mode===m?'active':'',`data-mode="${m}"`)).join('')}</div><div class="timer-face" id="timerFace"><div class="timer-digits"><span id="timeDigits">25:00</span><small id="timerMode">TIME TO FOCUS</small></div></div><input id="timerGoal" class="input-subtle" placeholder="One measurable task…" value="${esc(timer.goal||state.notes.intention||'')}"><div class="timer-controls">${btn(timer.running?'Pause':'▶ Start focus','timer-toggle','primary','id="timerToggle"')}${btn('↺','timer-reset','secondary','aria-label="Reset timer"')}</div><div class="session-dots">${[0,1,2,3].map(i=>`<i class="${i<timer.cycle%4?'filled':''}"></i>`).join('')}</div><p class="timer-note">${timer.cycle} focus sessions this cycle · breaks earn no XP</p><p class="timer-note">Breaks: walk, stretch, rest your eyes.<br>Keep social feeds closed.</p></div>`;}
function planView(){const d=day(),t=taskState();return `${heading('Your 154-day journey.','22 weeks · beginner-friendly DSA · a protected daily review block',btn('Go to next unfinished day →','next-unfinished'))}<div class="panel"><div class="day-nav">${btn('← Previous','prev-day')}<select id="daySelect" aria-label="Select preparation day">${config.days.map(x=>`<option value="${x.day}" ${x.day===d.day?'selected':''}>Day ${x.day} · ${esc(x.title)}</option>`).join('')}</select>${btn('Next →','next-day')}</div><div class="day-grid">${config.days.map(x=>{const z=taskState(x.day);return btn(String(x.day),'choose-day',`day-cell ${x.day===d.day?'active':''} ${z.backend&&z.dsa&&z.review?'done':''}`,`data-day="${x.day}" title="${esc(x.title)}" aria-label="Day ${x.day}: ${esc(x.title)}"`);}).join('')}</div></div><div class="panel day-detail"><div class="week-tag">WEEK ${d.week} / ${esc(d.week_name)} · ${esc(d.weekday)}</div><h2>Day ${d.day}: ${esc(d.title)}</h2><p>${esc(d.backend)}</p>${state.settings.startDate?`<p>Planned local date: ${plusDays(state.settings.startDate,d.day-1)} · lessons never skip automatically</p>`:''}<div class="budget-blocks"><div><b>${d.budget[0]} min</b>${d.weekday==='Saturday'?'Hands-on lab':d.weekday==='Sunday'?'Assessment':'Backend'}</div><div><b>${d.budget[1]} min</b>${d.weekday==='Sunday'?'Planning':'DSA'}</div><div><b>20 min</b>Spaced repetition</div></div><p><b>One bounded proof:</b> ${esc(d.focus)}</p><p><b>DSA:</b> ${esc(d.meta.name)} · ${esc(d.meta.difficulty)} · ${esc(d.meta.pattern)}<br>${esc(d.meta.outcome)}</p><p>${d.first_exposure&&d.meta.difficulty==='Medium'?'First Medium exposure: constraints, brute force and a guided optimized idea are a valid first session. Do not rush an independent solution.':''}${d.next_full_dsa?` Next full DSA slot: Day ${d.next_full_dsa}.`:''}</p><div class="inline-note"><b>Time budget:</b> ${d.minutes} allocated minutes. Optional 5-minute breaks come from backend/DSA time, never the protected 20-minute review. A 25/5 timer is adjustable; do not add extra breaks and silently extend the plan.</div><div class="flex">${btn(t.backend?'✓ Backend attempted':'Open backend block','task-backend','primary')}${btn(t.dsa?'✓ DSA / planning attempted':'Open DSA / planning','task-dsa')}${btn(t.review?'✓ Review attempted':'Open review block','task-review')}${btn('Questions for this day →','day-bank')}</div><h3 style="margin-top:22px">Left over from today</h3><textarea data-note="leftover-${d.day}" placeholder="Task, exact blocker, next action and retry date…">${esc(state.notes['leftover-'+d.day]||'')}</textarea></div>`;}
function tracksView(){if(selectedTrack){const t=tracks().find(x=>x.id===selectedTrack);if(!t){selectedTrack=null;return tracksView();}return `${heading(esc(t.title),esc(t.description||'Your custom learning track'),btn('← All tracks','all-tracks'))}<div class="panel">${t.lessons.map(l=>`<div class="list-row"><span class="task-icon">${lessonIsDone(l)?'✓':'◌'}</span><div><b>${esc(l.title)}</b><p>${esc(l.summary||'')} · ${l.minutes||25} min</p></div>${btn(l.day?'Open day →':'Practice →','lesson','secondary',`data-track="${esc(t.id)}" data-id="${esc(l.id)}"`)}</div>`).join('')}</div>`;}
return `${heading('Follow your curiosity.','The interview plan stays intact. Explore optional tracks at your own pace.',btn('+ Add a track','add-track','primary'))}<div class="toolbar"><input id="trackSearch" aria-label="Search tracks" placeholder="Search tracks or topics…" value="${esc(query)}">${btn('Import track JSON','import-track')}${btn('Export track template','template')}</div><div class="track-grid">${tracks().filter(t=>(t.title+' '+t.description+' '+t.lessons.map(l=>l.title).join(' ')).toLowerCase().includes(query.toLowerCase())).map(t=>{const n=t.lessons.filter(lessonIsDone).length;return `<article class="track-card"><div class="flex"><div class="track-icon ${esc(t.color||'mint')}">${esc(t.icon||'◇')}</div>${t.optional?badge('OPTIONAL EXTENSION'):''}</div><h3>${esc(t.title)}</h3><p>${esc(t.description||'A track built around your next learning goal.')}</p><div class="progress"><span style="width:${n/t.lessons.length*100}%"></span></div><div class="hint-row"><span>${n} / ${t.lessons.length} practiced</span><span>${Math.round(n/t.lessons.length*100)}%</span></div>${btn('Explore track →','track','quiet',`data-id="${esc(t.id)}"`)}</article>`;}).join('')}</div>`;}
function lessonIsDone(l){return l.day?!!taskState(l.day).backend:!!state.lessonDone[l.id];}
function reviewsView(){const due=dueCards(state),todayCount=state.reviewLog.filter(x=>x.date===dayKey()).length;const active=reviewSelection?state.reviews[reviewSelection]:null;if(active){const q=questionMap.get(active.id);if(!q)return '<p>Card source unavailable. Restore its track or backup.</p>';return `${heading('Recall before you reveal.',`${todayCount}/2 cards today · maximum 2 × 8 minutes + 4 minutes correcting`,btn('← Review queue','review-list'))}<div class="panel review-workspace"><div class="review-instructions">Close notes. Answer aloud or write your answer first. R means unaided recall; A requires an independent proof. Guided attempts earn an honest retry.</div>${badge(active.guided?'WEAK ITEM · PRIORITY':'SCHEDULED REVIEW','mint')} ${badge(q.id)}<h2>${esc(q.question)}</h2><textarea id="recallAttempt" placeholder="Your answer from memory, or describe the trace/code you demonstrated…"></textarea><label class="checkbox-label"><input type="checkbox" id="spokenAttempt"> I answered aloud without notes.</label>${btn(reviewAnswer?'Reference shown':'Reveal reference answer','reveal-review','secondary')}<div id="referenceAnswer" ${reviewAnswer?'':'hidden'}><div class="answer-label">REFERENCE · VERIFY WITH YOUR PROOF</div><div class="answer">${esc(q.answer)}</div><label class="checkbox-label"><input id="appliedCheck" type="checkbox"> I independently coded, traced, tested or diagnosed this.</label><label class="checkbox-label"><input id="guidedApplication" type="checkbox"> Recall worked, but application needed guidance (G); retry tomorrow.</label><input id="applicationEvidence" class="input" placeholder="Application evidence: test, fresh example or diagnosis" style="width:100%"><div class="review-grade">${btn('G · Needed guidance ↻','grade-guided','secondary')}${btn('R · Recalled unaided ✓','grade-recalled','primary')}</div><p class="muted" style="font-size:11px">G retries tomorrow. R advances the calendar interval. Application is recorded separately; it never follows automatically from R.</p></div></div>`;}
const upcoming=Object.values(state.reviews).filter(r=>r.due&&r.due>dayKey()).sort((a,b)=>a.due.localeCompare(b.due));return `${heading('Give memory a return ticket.','Weak items first. Two cards today. No backlog marathon.',btn('Create a recall card','new-card','primary'))}<div class="stats-grid">${statCard('DUE & OVERDUE',due.length,'Priority: guided → oldest due')}${statCard('TODAY’S CAP',`${todayCount}<span> / 2</span>`,'Two 8-minute cards + 4-minute log')}${statCard('SCHEDULED',Object.keys(state.reviews).length,'Intervals from the actual learning date')}${statCard('NEXT TARGET',upcoming[0]?esc(upcoming[0].due):'—','Later reviews remain visible')}</div><div class="inline-note">Target offsets: +1, +3, +7, +14, +30 days after learning. Late successful reviews advance only one stage; failures retry tomorrow. This is a transparent calendar scheduler, not Anki’s FSRS. Anki reviews keep their own scheduler.</div>${due.length?due.map((r,i)=>{const q=questionMap.get(r.id);return `<div class="list-row"><span class="task-icon">↻</span><div><b>${esc(q?.question||r.id)}</b><p>${esc(r.id)} · due ${r.due}${r.guided?' · guidance needed':''}${i>=Math.max(0,2-todayCount)?' · queued beyond today’s cap':''}</p></div>${btn('Recall →','open-review','secondary',`data-id="${esc(r.id)}" ${todayCount>=2?'disabled':''}`)}</div>`;}).join(''):`<div class="empty-state">${todayCount?'Your two-card review block is complete. Use the final four minutes to record corrections.':'No cards due. Complete a learning block, queue an interview question, or create your own card.'}</div>`}<div style="margin-top:20px">${btn('Log the review block as attempted','finish-review','primary')}</div><div class="section-heading"><h2>Upcoming returns</h2><small>${upcoming.length} scheduled</small></div><div class="panel">${upcoming.slice(0,15).map(r=>`<div class="list-row"><div><b>${esc(questionMap.get(r.id)?.title||r.id)}</b><p>${esc(r.id)} · ${esc(questionMap.get(r.id)?.question||'')}</p></div><span class="tag">${r.due}</span></div>`).join('')||'<p class="muted">Your first learning block will plant the first review.</p>'}</div>`;}
function bankView(){const qs=questions().filter(q=>(filter==='all'||(filter==='day'?q.day===state.currentDay:q.kind===filter))&&(q.question+' '+q.title+' '+q.id).toLowerCase().includes(query.toLowerCase()));return `${heading('Practice the conversation.',`${questions().length.toLocaleString()} day-aligned prompts · answer aloud before checking`,btn(`Send selected to Anki (${chosen.size})`,'send-anki','secondary'))}<div class="toolbar"><input id="bankSearch" aria-label="Search interview questions" placeholder="Search question, topic or ID…" value="${esc(query)}"><select id="bankFilter" aria-label="Filter questions">${[['all','All questions'],['day','Current day'],['T','Technical'],['S','Senior scenarios'],['C','DSA / coding']].map(([v,l])=>`<option value="${v}" ${filter===v?'selected':''}>${l}</option>`).join('')}</select>${btn('Export selected TSV','export-tsv')}</div><div class="hint-row" style="margin-bottom:18px"><span>${qs.length} matches · showing first 60 · search to narrow</span><span>${chosen.size} selected</span></div>${qs.slice(0,60).map(q=>{const a=state.assessments[q.id]||{};return `<article class="question-card">${badge(q.id)} ${badge(q.kind==='S'?'SENIOR SCENARIO':q.kind==='C'?'CODING / DSA':'TECHNICAL')} <span class="muted" style="font-size:10px">${q.day?'Day '+q.day+' · ':''}${esc(q.title||'Custom card')}</span><h3>${esc(q.question)}</h3><label class="checkbox-label"><input type="checkbox" class="anki-select" data-id="${esc(q.id)}" ${chosen.has(q.id)?'checked':''}> Select for Anki / TSV</label><div class="question-actions">${btn('Try recall','practice','primary',`data-id="${esc(q.id)}"`)}${btn(state.reviews[q.id]?'↻ Scheduled':'＋ Queue for revision','queue-card','secondary',`data-id="${esc(q.id)}"`)}<span class="muted" style="font-size:10px">${a.r?'R ✓ ':''}${a.a?'A ✓ ':''}${a.g?'G · retry ':''}</span></div></article>`;}).join('')||'<div class="empty-state">No questions match. Try a topic or an exact ID.</div>'}`;}
function flowsView(){return `${heading('Trace the whole request.','Explain each boundary, then name what can fail between two steps.')}<div class="flow-list">${config.flows.map((f,i)=>`<article class="flow-step"><div><h3>${esc(f.title)}</h3><p>${esc(f.detail)}</p>${btn('Practice this boundary →','flow-practice','quiet',`data-index="${i}"`)}</div></article>`).join('')}</div><div class="inline-note">This is a reference journey, not a requirement that every request pass through every component. Follow the synchronous response and asynchronous recovery paths separately.</div>`;}
function notesView(){const keys=Object.keys(state.notes).filter(k=>state.notes[k]&&k!=='intention');return `${heading('Leave a useful trail.','Capture the blocker, the evidence and the next action.',btn('+ New note','new-note','primary'))}<div class="settings-grid"><div><h2>Notes & carry-over</h2>${keys.map(k=>`<article class="note-card"><div class="flex"><b>${esc(k.replace('leftover-','Day '))}</b>${btn('Remove','remove-note','quiet',`data-key="${esc(k)}"`)}</div><textarea data-note="${esc(k)}">${esc(state.notes[k])}</textarea><small class="muted">Saved as you type</small></article>`).join('')||'<div class="empty-state" style="margin-top:15px">Your daily carry-over and study notes will appear here.</div>'}</div><div class="panel"><h2>Small next actions</h2><form id="todoForm" class="flex" style="margin-top:18px"><input id="todoText" required maxlength="400" placeholder="One specific next action…" style="flex:1">${btn('Add','add-todo','primary','type="submit"')}</form>${state.todos.map(t=>`<div class="todo-row ${t.done?'done':''}"><input class="todo-check" type="checkbox" data-id="${esc(t.id)}" aria-label="Complete ${esc(t.text)}" ${t.done?'checked':''}><span>${esc(t.text)}</span>${btn('Edit','edit-todo','quiet',`data-id="${esc(t.id)}" aria-label="Edit task"`)}${btn('×','remove-todo','',`data-id="${esc(t.id)}" aria-label="Remove task"`)}</div>`).join('')}<p class="timer-note">A next action should fit one session. Moving a task is planning, not failure.</p></div></div>`;}
function analyticsView(){const s=stats(state),now=dayKey(),last=Array.from({length:7},(_,i)=>plusDays(now,i-6));const minutes=k=>state.sessions.filter(x=>x.date===k&&x.mode==='focus').reduce((n,x)=>n+x.seconds/60,0),max=Math.max(25,...last.map(minutes));const attempts=state.reviewLog.filter(x=>x.result==='R'||x.result==='G'),accuracy=attempts.length?Math.round(attempts.filter(x=>x.result==='R').length/attempts.length*100):0;const badges=[['First proof',s.applied>=1,'Demonstrate one independent application.'],['Memory keeper',attempts.filter(x=>x.result==='R').length>=5,'Recall five scheduled cards without notes.'],['A week of showing up',s.streak>=7,'Study on seven consecutive local dates.'],['First chapter',s.completed>=7,'Attempt all three blocks on seven days.']];return `${heading('Evidence over impressions.','Completion measures activity. Recall and application measure different skills.')}<div class="stats-grid">${statCard('PLAN COMPLETION',`${s.completed}<span> / 154</span>`,'All three blocks attempted')}${statCard('DELAYED RECALL',`${accuracy}<span>%</span>`,`${attempts.length} graded scheduled attempts`)}${statCard('INDEPENDENT PROOFS',s.applied,'Application never inferred from recall')}${statCard('TOTAL XP',s.xp,`Level ${s.level} · ${s.streak}-day current streak`)}</div><div class="settings-grid"><div class="panel"><h2>Your last seven days</h2><p class="muted" style="font-size:11px;margin-top:7px">Completed focus-timer minutes, not page-open time.</p><div class="chart-bars">${last.map(k=>`<div class="chart-day"><span>${Math.round(minutes(k))}m</span><div class="chart-bar" style="height:${minutes(k)/max*100}px"></div><span>${new Date(k+'T12:00:00').toLocaleDateString(undefined,{weekday:'short'})}</span></div>`).join('')}</div></div><div class="panel"><h2>Attention & retention</h2><div class="metric-row"><div><strong>${Math.round(Math.max(0,...state.sessions.filter(x=>x.mode==='focus').map(x=>x.seconds))/60)}m</strong><span>Longest completed focus</span></div><div><strong>${Object.values(state.reviews).filter(r=>r.guided).length}</strong><span>Weak cards to revisit</span></div></div><p class="muted" style="font-size:12px;margin-top:22px">XP rewards honest attempts. It is not an interview-readiness score. Look for stronger delayed recall and more independent proofs over time.</p></div></div><div class="section-heading"><h2>Earned through practice</h2></div><div class="badge-grid">${badges.map(([name,earned,desc])=>`<div class="badge ${earned?'':'locked'}"><span style="font-size:25px">${earned?'✦':'◇'}</span><b>${name}</b><p>${desc}</p><small>${earned?'Earned':'In progress'}</small></div>`).join('')}</div>`;}
function settingsView(){return `${heading('Make this space yours.','Tune the method, protect your progress, and connect your tools.')}<div class="settings-grid"><section class="panel"><h2>Experience & focus</h2><label class="field">Your name<input id="settingName" value="${esc(state.settings.name)}" maxlength="60"></label><label class="field"><input id="settingSound" type="checkbox" ${state.settings.sound?'checked':''}> Play a completion chime</label><label class="field">Sound volume<input id="settingVolume" type="range" min="0" max="1" step="0.05" value="${state.settings.volume}"></label><div class="flex">${btn('♫ Test sound','test-sound')}${btn('Upload your own sound','upload-sound')}${state.settings.customAudio?btn('Use built-in chime','default-sound','quiet'):''}</div><p class="timer-note">Built-in: an original rising chime. The linked video contains Microsoft To Do sound variations; its audio is not bundled. Upload a short audio file (max 2 MB) to use your preferred sound.</p><label class="field"><input id="settingMotion" type="checkbox" ${state.settings.reducedMotion?'checked':''}> Reduce celebration motion</label><div class="flex"><label class="field">Focus minutes<input id="settingFocus" type="number" min="1" max="120" value="${state.settings.focus}"></label><label class="field">Short break<input id="settingShort" type="number" min="1" max="30" value="${state.settings.shortBreak}"></label><label class="field">Long break<input id="settingLong" type="number" min="1" max="60" value="${state.settings.longBreak}"></label></div><label class="field">Plan start (choose a Monday)<input id="settingStart" type="date" value="${esc(state.settings.startDate)}"></label><p class="timer-note">The plan advances when you select a day. Missed calendar days do not silently skip lessons.</p>${btn('Save preferences','save-settings','primary')}</section><section class="panel"><h2>AnkiConnect</h2><p class="muted" style="font-size:12px">Use Anki Desktop on the same computer as this browser. On a phone, export TSV and import it into your Anki workflow.</p><label class="field">Loopback endpoint<input id="ankiUrl" value="${esc(state.settings.ankiUrl)}"></label><label class="field">API key (session only, never exported)<input id="ankiKey" type="password" autocomplete="off" value="${esc(ankiKey)}"></label><div class="flex">${btn('Test connection','anki-connect','primary')}${btn('Setup guide','anki-help')}</div><div class="inline-note" id="ankiStatus" role="status">${esc(ankiStatus)}</div><label class="field">Deck<select id="ankiDeck"><option value="${esc(state.settings.ankiDeck)}">${esc(state.settings.ankiDeck)}</option>${ankiDecks.filter(x=>x!==state.settings.ankiDeck).map(d=>`<option>${esc(d)}</option>`).join('')}</select></label><div class="flex">${btn('Create deck','anki-create-deck')}${btn('Show due count','anki-due')}${btn('Open review in Anki','anki-review')}</div><p class="timer-note">Selected question export uses Basic Front/Back notes and stable per-question tags. Anki owns card scheduling; reviews there do not automatically earn an application proof here.</p>${btn('Export selected cards as TSV','export-tsv','quiet')}</section><section class="panel"><h2>Backup & portability</h2><p class="muted" style="font-size:12px">Progress, notes, custom tracks, timer sessions and review history stay in this browser. There is no automatic cross-device sync.</p><div class="flex" style="margin-top:18px">${btn('Export backup JSON','backup','primary')}${btn('Restore backup','restore')}</div><p class="timer-note">Restore replaces this browser’s progress after a preview and confirmation. Your current state is downloaded first.</p><div class="reset-progress-panel"><h3>Start fresh</h3><p class="timer-note">Erase learning progress in this browser and return to Day 1. Keep your tracks, flashcards, notes, tasks and preferences.</p>${btn('Erase learning progress','erase-progress','danger')}</div><h3 style="margin-top:25px">Configurable tracks</h3><p class="muted" style="font-size:12px;margin:10px 0">Add a track in the app, or import a JSON track. IDs are stable so changing titles does not erase progress.</p><div class="flex">${btn('Download JSON template','template')}${btn('Import a track','import-track')}</div></section><section class="panel"><h2>What came from the reference?</h2><p class="muted" style="font-size:12px">Observed interface features, working behavior and the additions in this version are documented separately.</p><div class="flex" style="margin-top:18px">${btn('Feature comparison','audit')}${btn('Study method','nav','secondary','data-view="method"')}</div><p class="timer-note">Baseline: all 154 day topics, tasks, DSA assignments and 3,278 question IDs. Reference answers are concise draft study aids, not executed proofs or automatic grading.</p><p class="timer-note"><a href="https://java-aws-kafka-mastery.vercel.app/" target="_blank" rel="noopener">Reference learning site ↗</a> · <a href="https://www.youtube.com/watch?v=dkw-k_mtHLE" target="_blank" rel="noopener">Sound reference ↗</a></p></section></div>`;}
function methodView(){return `${heading('A system for remembering.','The reward is visible progress. The goal is independent understanding.')}<div class="method-grid"><div class="panel"><span class="track-icon">↻</span><h2 style="margin-top:17px">Spaced repetition</h2><p>Return at +1, +3, +7, +14 and +30 days after actual learning. Core days enroll a backend and a DSA card. Other days use a next-day return plus the plan’s weekly revision. Queue additional questions deliberately.</p><p>Two 8-minute cards, then 4 minutes checking and recording corrections. Weak cards take priority; excess stays visible for later. Failure returns tomorrow; a missed day never forces a marathon.</p></div><div class="panel"><span class="track-icon blue">◎</span><h2 style="margin-top:17px">Active recall</h2><p>Close notes. Explain aloud, write the mechanism, trace a fresh input or reproduce the bug. Only then reveal the reference and correct your answer.</p><p><b>R:</b> accurate unaided explanation.<br><b>A:</b> independent implementation, test, trace or diagnosis.<br><b>G:</b> notes, hints or a reference were needed.</p><p>Record R and G together in your notes if recall worked but coding needed guidance. Application stays a separate evidence check.</p></div><div class="panel"><span class="track-icon amber">◷</span><h2 style="margin-top:17px">Pomodoro & attention</h2><p>Start with 25 minutes of one measurable task and a 5-minute break. After four focus sessions, choose a 15–30 minute recovery break. Adjust the focus length to the actual task.</p><p>Put the phone away, silence notifications, keep one intention visible, and gently return when attention wanders. Walk, stretch or rest your eyes during breaks; avoid social feeds.</p><p>Track delayed recall and useful focus, not hours with a page open. Support learning with regular sleep (roughly 7–9 hours for most adults) and movement.</p></div></div><div class="panel" style="margin-top:22px"><h2>The realistic time contract</h2><div class="budget-blocks"><div><b>120 min</b>Mon–Fri · 55 backend + 45 DSA + 20 review</div><div><b>180 min</b>Saturday · 140 lab + 20 correction + 20 review</div><div><b>60 min</b>Sunday · 25 assessment + 15 planning + 20 review</div></div><p class="muted" style="font-size:12px">Those are allocated blocks. To stay within the elapsed-time cap, take short breaks from backend/DSA allocation; protect the 20-minute review. That slightly reduces active practice time and is an explicit adaptation from the PDF. Optional AWS/Kafka extensions replace elective time or happen later; they are not extra daily obligations.</p><p class="muted" style="font-size:12px;margin-top:12px">First DSA Medium exposure may end with a brute force attempt and guided understanding. Complete independent coding at the named return slot. The question bank is a reusable bank, not a daily quota.</p></div>`;}
function openTask(kind){if(kind==='review'){navigate('reviews');return;}const d=day();dialog(kind==='backend'?(d.weekday==='Sunday'?'Weekly assessment':d.title):(d.weekday==='Sunday'?'Planning & carry-over':d.meta.name),`<span class="tag">DAY ${d.day} · ${d.budget[kind==='backend'?0:1]} MIN ALLOCATED</span><h3>${kind==='backend'?'One bounded goal':esc(d.meta.pattern)}</h3><p>${esc(kind==='backend'?d.focus:d.weekday==='Sunday'?'Select one important unfinished item, check next week’s prerequisites and set a retry date. DSA is an oral trace inside the assessment today.':d.meta.outcome)}</p><p>${esc(kind==='backend'?d.backend:d.first_exposure&&d.meta.difficulty==='Medium'?'Understand constraints, attempt brute force, then inspect one optimized idea. A guided partial attempt is an honest result. Do not assume a new Medium fits one session.':'State the invariant, implement in Java, test edge cases and explain time/space complexity.')}</p><label class="field">Evidence / exact blocker<textarea id="taskEvidence" placeholder="What did you attempt or demonstrate? What remains?">${esc(state.notes[`evidence-${d.day}-${kind}`]||'')}</textarea></label><label class="checkbox-label"><input id="taskApplied" type="checkbox"> I independently demonstrated today’s ${kind==='backend'?'backend concept':'DSA solution'} (A).</label><p class="muted">Marking attempted records honest effort. It does not claim mastery.</p>`,btn('Start a focus session','task-focus','secondary',`data-kind="${kind}"`)+btn(taskState()[kind]?'Save evidence':'Mark attempted · +20 XP','finish-task','primary',`data-kind="${kind}"`));}
function finishTask(kind){const d=day(),e=$('#taskEvidence').value.trim();if(!e)return toast('Record a short proof or the exact blocker first.');const key=kind==='backend'?d.questions.find(q=>q.kind==='T').id:d.questions.find(q=>q.kind==='C').id;state.notes[`evidence-${d.day}-${kind}`]=e;state.tasks[d.day]={...taskState(),[kind]:true};state.activity[dayKey()]=true;if($('#taskApplied').checked){state.assessments[key]={...(state.assessments[key]||{}),a:true};award(state,`application:${key}`,30);}if(d.weekday!=='Sunday'){const ints=d.core?config.reviewIntervals:[1,7,14,30];enroll(state,key,ints);state.reviews[key].intervals=ints;}const won=award(state,`task:${d.day}:${kind}`,20);save();close();render();if(won)celebrate('Block attempted. Your next review is scheduled. +20 XP');else toast('Evidence saved.');}
function practice(id){const q=questionMap.get(id);dialog(`${id} · Active recall`,`<h3>${esc(q.question)}</h3><textarea id="practiceAttempt" placeholder="Your answer from memory…"></textarea><label class="checkbox-label"><input id="practiceSpoken" type="checkbox"> I answered aloud without notes.</label>${btn('Reveal reference','practice-reveal','secondary')}<div id="practiceRef" hidden><div class="answer-label">REFERENCE ANSWER</div><p>${esc(q.answer)}</p><label class="checkbox-label"><input id="practiceR" type="checkbox"> R · I recalled this accurately without notes.</label><label class="checkbox-label"><input id="practiceA" type="checkbox"> A · I independently applied it.</label><label class="checkbox-label"><input id="practiceG" type="checkbox"> G · I needed guidance for at least part of the task.</label><input id="practiceEvidence" class="input" placeholder="Independent application evidence (required for A)" style="width:100%"></div>`,btn('Save assessment & schedule','practice-save','primary',`data-id="${esc(id)}" disabled id="practiceSave"`));}
function finishReview(){const n=state.reviewLog.filter(x=>x.date===dayKey()).length;dialog('Close the 20-minute review block',`<p>${n} scheduled card(s) reviewed today. If no cards were due, use a cold prompt from the current day. Spend the final four minutes correcting and logging.</p><label class="field">Correction, weak ID or next action<textarea id="reviewEvidence" placeholder="What did you recall? What needs another attempt?"></textarea></label>`,btn('Log review as attempted · +20 XP','confirm-review','primary'));}
function openReview(id){if(state.reviewLog.filter(x=>x.date===dayKey()).length>=config.reviewDailyLimit)return toast('Your two-card cap is reached. Correct and log; leave the rest for later.');const r=state.reviews[id];if(!r||!r.due||r.due>dayKey())return toast('This card is not due yet.');view='reviews';reviewSelection=id;reviewAnswer=false;render();}
function recordGrade(result){const id=reviewSelection;const attempt=$('#recallAttempt').value.trim(),spoken=$('#spokenAttempt').checked;if(!attempt&&!spoken)return toast('Make a retrieval attempt before grading.');const applied=$('#appliedCheck').checked,guidedApplication=$('#guidedApplication').checked,e=$('#applicationEvidence').value.trim();if(applied&&guidedApplication)return toast('Choose independent application or guided application for this attempt, not both.');if(applied&&!e)return toast('Add an independent application proof before marking A.');grade(state,id,result,state.reviews[id].intervals||config.reviewIntervals,dayKey(),applied,guidedApplication);if(attempt)state.notes[`recall-${id}`]=attempt+(e?'\nApplication: '+e:'');save();reviewSelection=null;reviewAnswer=false;render();celebrate(result==='R'?(guidedApplication?'Recall logged as R; application logged as G. Retry tomorrow. +15 XP':'Recalled unaided. Next return scheduled. +15 XP'):'Honest attempt logged. Retry tomorrow. +5 XP');}
function timerLength(mode){return (mode==='focus'?state.settings.focus:mode==='short'?state.settings.shortBreak:state.settings.longBreak)*60;}
function updateTimer(){if(timer.running)timer.remaining=Math.max(0,Math.ceil((timer.end-Date.now())/1000));const digits=$('#timeDigits');if(digits){digits.textContent=`${String(Math.floor(timer.remaining/60)).padStart(2,'0')}:${String(timer.remaining%60).padStart(2,'0')}`;$('#timerFace').style.setProperty('--timer-angle',`${(1-timer.remaining/timer.total)*360}deg`);$('#timerMode').textContent=timer.mode==='focus'?'TIME TO FOCUS':'REST YOUR ATTENTION';$('#timerToggle').textContent=timer.running?'Pause':timer.mode==='focus'?'▶ Start focus':'▶ Start break';}if(timer.running&&timer.remaining===0){timer.running=false;state.sessions.push({id:timer.id,date:dayKey(),seconds:timer.total,mode:timer.mode,goal:timer.goal});if(timer.mode==='focus'){state.activity[dayKey()]=true;award(state,'focus:'+timer.id,10);timer.cycle++;}save();saveTimer();render();celebrate(timer.mode==='focus'?`Focus session complete. ${timer.cycle%4===0?'Consider a longer recovery break.':'Take a short break.'}`:'Break complete. Choose your next intention.');}}
setInterval(updateTimer,500);
function resetTimer(mode=timer.mode){timer={...timer,mode,total:timerLength(mode),remaining:timerLength(mode),running:false,end:0,id:null};saveTimer();render();}
function toggleTimer(){if(timer.remaining<=0)resetTimer();if(timer.running){timer.remaining=Math.max(0,Math.ceil((timer.end-Date.now())/1000));timer.running=false;}else{timer.goal=$('#timerGoal')?.value.trim()||timer.goal;if(timer.mode==='focus'&&!timer.goal)return toast('Set one measurable task before starting.');timer.running=true;timer.end=Date.now()+timer.remaining*1000;timer.id ||= crypto.randomUUID();}saveTimer();updateTimer();}
function trackTemplate(){return {id:'public-speaking',title:'Confident public speaking',description:'A reusable example: any subject can be a learning track.',icon:'◎',color:'mint',lessons:[{id:'speaking-01',title:'A clear two-minute story',summary:'Record a beginning, a decision and an outcome.',minutes:25,prompt:'Explain a real decision clearly in two minutes.',answer:'Check that your listener can identify the context, your decision, its reason and the result. Record one improvement, then try again without notes.'}]};}
function addTrackDialog(){dialog('Create your next learning track',`<label class="field">Track title<input id="newTrackTitle" placeholder="e.g. Mastering system design" maxlength="150"></label><label class="field">Description<input id="newTrackDesc" placeholder="What will you be able to demonstrate?" maxlength="500"></label><label class="field">Lessons, one per line<textarea id="newTrackLessons" placeholder="Clarify requirements\nEstimate capacity\nDefend a partitioning key"></textarea></label><p>Each lesson can be completed, practiced and scheduled for recall. For detailed prompts, answers and resources, use the JSON template.</p>`,btn('Create track','save-track','primary'));}
async function readFile(accept){return new Promise(resolve=>{const input=document.createElement('input');input.type='file';input.accept=accept;input.hidden=true;document.body.appendChild(input);input.onchange=()=>{const file=input.files[0]||null;input.remove();resolve(file);};input.addEventListener('cancel',()=>{input.remove();resolve(null);});input.click();});}
async function importTrack(){const file=await readFile('.json,application/json');if(!file)return;if(file.size>3000000)throw Error('Track file must be under 3 MB.');const raw=JSON.parse(await file.text()),t=validateTrack(raw);if(tracks().some(x=>x.id===t.id))throw Error('That track ID already exists. Use a new ID; existing progress was preserved.');const existingIds=new Set(tracks().flatMap(t=>t.lessons.map(l=>l.id)));if(t.lessons.some(l=>existingIds.has(l.id)))throw Error('A lesson ID already exists in another track. Use globally unique lesson IDs.');state.customTracks.push(t);save();selectedTrack=t.id;view='tracks';render();toast('Track imported. Your existing plan is unchanged.');}
function lessonDialog(trackId,id){const l=tracks().find(t=>t.id===trackId).lessons.find(l=>l.id===id);if(l.day){state.currentDay=l.day;save();navigate('plan');return;}dialog(l.title,`<p>${esc(l.summary||'')}</p>${l.resource&&/^https?:\/\//.test(l.resource)?`<p><a href="${esc(l.resource)}" target="_blank" rel="noopener">Open learning resource ↗</a></p>`:''}<h3>Recall & demonstrate</h3><p>${esc(l.prompt||l.title)}</p><label class="field">Your evidence / blocker<textarea id="lessonEvidence" placeholder="What did you do? What will you revisit?">${esc(state.notes['lesson-'+id]||'')}</textarea></label>`,btn('Mark practiced & schedule recall','finish-lesson','primary',`data-track="${esc(trackId)}" data-id="${esc(id)}"`));}
function quickResults(term=''){const q=term.toLowerCase().trim();const days=config.days.filter(d=>(d.title+' '+d.day).toLowerCase().includes(q)).slice(0,4);const ts=tracks().filter(t=>t.title.toLowerCase().includes(q)).slice(0,3);const qs=q?questions().filter(x=>(x.id+' '+x.question).toLowerCase().includes(q)).slice(0,5):[];return [...days.map(d=>`<div class="list-row"><div><b>Day ${d.day} · ${esc(d.title)}</b></div>${btn('Open','search-day','secondary',`data-day="${d.day}"`)}</div>`),...ts.map(t=>`<div class="list-row"><div><b>${esc(t.title)}</b><p>Learning track</p></div>${btn('Explore','search-track','secondary',`data-id="${esc(t.id)}"`)}</div>`),...qs.map(x=>`<div class="list-row"><div><b>${esc(x.id)}</b><p>${esc(x.question)}</p></div>${btn('Practice','practice','secondary',`data-id="${esc(x.id)}"`)}</div>`)].join('')||'<p>No results. Try a topic or question ID.</p>';}
function quickSearch(){if(!config)return;dialog('Find your next idea',`<input id="quickQuery" class="input" aria-label="Search days, tracks and questions" placeholder="Topic, day or question ID…" style="width:100%"><div id="quickResults">${quickResults()}</div>`);$('#quickQuery').focus();}
function newCard(){dialog('Create an active-recall card',`<label class="field">Prompt<textarea id="cardFront" placeholder="A focused question you can answer aloud…"></textarea></label><label class="field">Reference / answer<textarea id="cardBack" placeholder="The essential mechanism, assumptions and an example…"></textarea></label>`,btn('Create & schedule','save-card','primary'));}
function audit(){const rows=[['Dashboard & track cards','Observed: Java, Spring Boot, Microservices, Kafka, AWS and Interview Prep.','Configurable track catalogue; optional AWS and Kafka extensions.'],['Completion & progress','A lesson visit increased the topic-completed count.','Explicit attempted blocks; recall and independent application stay separate.'],['XP, levels, streaks & metrics','Visible XP/level, streak, study time, velocity, heatmap and readiness indicators.','XP, levels, current streak, honest completion, delayed-recall accuracy and focus minutes. No invented readiness/velocity score.'],['Study planner','Roadmap labelled 45-day, displaying 43 sessions with labels extending to Day 60.','Preserved 154-day sequence, named DSA return slots and daily time allocation.'],['Interview questions & daily warmup','Daily prompt, answer reveal and interview-topic sections visible.','3,278 preserved question IDs, answer-after-attempt, R/A/G and Anki selection.'],['Notes & tasks','Notes area and add/edit/delete task controls visible.','Autosaved notes, carry-over, task add/edit/complete/remove and backup export.'],['Request flows','20 linked steps from browser/DNS through production flow.','Six explainable boundaries with concrete failure practice.'],['Search, themes & navigation','Search, command-palette UI, theme and collapsible sidebars visible.','Global command search (Ctrl/Cmd+K or /), track/question search, light/dark themes and mobile navigation.'],['Settings & notifications','Buttons visible; Settings did not change the viewed panel in inspection. Notification count was visible.','Working preferences, sound controls, custom audio, timer settings and backup. No unverified notification feature claimed.'],['Pomodoro, spaced repetition, Anki','Not observed in inspected reference sections.','Protected two-card review queue, target intervals, guided retries, focus/break timer and optional AnkiConnect.']];dialog('Reference feature audit',`<p>Inspected 17 November 2026. This is a UI/behavior audit of the available pages, not a claim to have tested every resource or hidden feature.</p><table class="audit-table"><thead><tr><th>Area</th><th>Reference evidence</th><th>This workspace</th></tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table><p>Content is an original workspace built around your plan. Reference topic headings informed optional tracks; long lesson text and video audio were not copied.</p>`);}
function ankiHelp(){dialog('Connect your desktop Anki',`<p>1. Install Anki Desktop and the AnkiConnect add-on (2055492159), then keep Anki running on the same computer as your browser.</p><p>2. Keep AnkiConnect bound to 127.0.0.1. Use Test connection to request permission; approve this exact site origin in Anki. If configuration is needed, add only the origin below to webCorsOriginList, preserving existing trusted origins.</p><pre>${esc(location.origin)}</pre><p>3. If your add-on uses an API key, enter it here. It stays in memory for this session and is excluded from backups.</p><p>4. Select interview questions, choose a Basic Front/Back-compatible deck, then send selected cards. Each note has a stable question-ID tag to skip repeat exports. Review in Anki so its own scheduler manages spacing.</p><p>HTTPS-to-loopback requests can be blocked by browser mixed-content, local-network permission or CORS policy. This integration is a provision, not a guaranteed remote connection. If it is blocked, download selected TSV cards and import them into Anki. On Android, localhost points to the phone, not your PC; use the TSV path.</p><p>References: <a href="https://github.com/FooSoft/anki-connect" target="_blank" rel="noopener">AnkiConnect project and current repository ↗</a>. API version 6; individual installations/models may vary.</p>`);}
function captureAnki(){if($('#ankiUrl'))state.settings.ankiUrl=$('#ankiUrl').value.trim();if($('#ankiKey'))ankiKey=$('#ankiKey').value;if($('#ankiDeck'))state.settings.ankiDeck=$('#ankiDeck').value;save();}
async function callAnki(action,params={}){return ankiRequest(state.settings.ankiUrl,action,params,ankiKey);}
async function connectAnki(){captureAnki();ankiStatus='Connecting to local Anki…';$('#ankiStatus').textContent=ankiStatus;try{const p=await callAnki('requestPermission');if(p.permission!=='granted')throw Error('Permission was not granted in Anki.');const version=await callAnki('version');if(version<6)throw Error('AnkiConnect API version 6 is required.');ankiDecks=await callAnki('deckNames');ankiModels=await callAnki('modelNames');ankiConnected=true;ankiStatus=`Connected · API ${version} · ${ankiDecks.length} decks`;render();}catch(e){ankiConnected=false;ankiStatus='Not connected: '+e.message+'. See setup guide or export TSV.';render();}}
async function sendAnki(){if(!chosen.size)return toast('Select questions in Interview practice first.');if(chosen.size>100)return toast('Send at most 100 selected cards per batch.');if(!ankiConnected){navigate('settings');return toast('Connect Anki first. Your selected questions are preserved.');}const fields=await callAnki('modelFieldNames',{modelName:'Basic'});if(!fields.includes('Front')||!fields.includes('Back'))throw Error('Basic must have Front and Back fields. Use TSV for a different model.');let added=0,skipped=0;for(const id of chosen){const q=questionMap.get(id);if(!q)continue;const tag='rfid_'+id.replace(/[^A-Za-z0-9_]/g,'_');const existing=await callAnki('findNotes',{query:'tag:'+tag});if(existing.length){skipped++;continue;}const result=await callAnki('addNote',{note:{deckName:state.settings.ankiDeck,modelName:'Basic',fields:{Front:esc(id)+'<br>'+esc(q.question),Back:esc(q.answer).replace(/\n/g,'<br>')},options:{allowDuplicate:false},tags:['recall_forge',tag]}});if(result)added++;else skipped++;}toast(`Anki export: ${added} added, ${skipped} skipped. Anki owns the review schedule.`);}
function exportTSV(){if(!chosen.size)return toast('Select one or more questions first.');const clean=x=>String(x).replace(/[\t\r\n]+/g,' ');const lines=[...chosen].map(id=>questionMap.get(id)).filter(Boolean).map(q=>`${clean(q.id+' · '+q.question)}\t${clean(q.answer)}\t${'recall_forge rfid_'+q.id.replace(/[^A-Za-z0-9_]/g,'_')}`);download('Recall_Forge_Selected_Cards.tsv',lines.join('\n'),'text/tab-separated-values');toast(`${lines.length} cards exported: Front, Back, Tags. Import as plain text in Anki.`);}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;try{switch(a){case'nav':navigate(el.dataset.view);break;case'search-day':state.currentDay=Number(el.dataset.day);save();close();navigate('plan');break;case'search-track':view='tracks';selectedTrack=el.dataset.id;close();render();break;case'close':close();break;case'task-backend':openTask('backend');break;case'task-dsa':openTask('dsa');break;case'task-review':openTask('review');break;case'finish-task':finishTask(el.dataset.kind);break;case'task-focus':timer.goal=$('#taskEvidence').value.trim()||day().focus;close();navigate('today');$('#timerGoal').value=timer.goal;break;case'finish-review':finishReview();break;case'confirm-review':{const evidence=$('#reviewEvidence').value.trim();if(!evidence)return toast('Log a correction, weak ID or cold-recall attempt.');state.notes['review-'+state.currentDay]=evidence;state.tasks[state.currentDay]={...taskState(),review:true};state.activity[dayKey()]=true;const first=award(state,'task:'+state.currentDay+':review',20);save();close();render();if(first)celebrate('Review protected. Progress saved. +20 XP');break;}case'choose-day':state.currentDay=Number(el.dataset.day);save();render();break;case'prev-day':state.currentDay=Math.max(1,state.currentDay-1);save();render();break;case'next-day':state.currentDay=Math.min(154,state.currentDay+1);save();render();break;case'next-unfinished':state.currentDay=config.days.find(d=>{const t=taskState(d.day);return !t.backend||!t.dsa||!t.review;})?.day||154;save();render();break;case'day-bank':view='bank';filter='day';render();break;case'track':selectedTrack=el.dataset.id;render();break;case'all-tracks':selectedTrack=null;render();break;case'lesson':lessonDialog(el.dataset.track,el.dataset.id);break;case'finish-lesson':{const t=tracks().find(t=>t.id===el.dataset.track),l=t.lessons.find(l=>l.id===el.dataset.id),ev=$('#lessonEvidence').value.trim();if(!ev)return toast('Record your attempt or evidence first.');state.lessonDone[l.id]=true;state.notes['lesson-'+l.id]=ev;const id='L-'+l.id;if(!questionMap.has(id)){state.customCards.push({id,title:t.title,kind:'T',question:l.prompt||l.title,answer:l.answer||l.summary||'Check your recorded evidence against the learning objective.'});rebuildMap();}enroll(state,id,config.reviewIntervals);state.activity[dayKey()]=true;const first=award(state,'lesson:'+l.id,20);save();close();render();if(first)celebrate('Lesson practiced. Recall return scheduled. +20 XP');break;}case'add-track':addTrackDialog();break;case'save-track':{const title=$('#newTrackTitle').value.trim(),names=$('#newTrackLessons').value.split('\n').map(x=>x.trim()).filter(Boolean);if(!title||!names.length)return toast('Add a title and at least one lesson.');const id='track-'+crypto.randomUUID();const t=validateTrack({id,title,description:$('#newTrackDesc').value.trim(),icon:'◇',color:'mint',lessons:names.map((title,i)=>({id:id+'-'+i,title,minutes:25,summary:'Define one measurable outcome and record a proof.'}))});state.customTracks.push(t);save();close();selectedTrack=id;view='tracks';render();break;}case'import-track':await importTrack();break;case'template':download('Recall_Forge_Track_Template.json',JSON.stringify(trackTemplate(),null,2));break;case'queue-card':enroll(state,el.dataset.id,config.reviewIntervals);save();render();toast('Scheduled from today at +1, +3, +7, +14, +30.');break;case'practice':practice(el.dataset.id);break;case'practice-reveal':if(!$('#practiceAttempt').value.trim()&&!$('#practiceSpoken').checked)return toast('Attempt the answer first, aloud or in writing.');$('#practiceRef').hidden=false;$('#practiceSave').disabled=false;break;case'practice-save':{const id=el.dataset.id,r=$('#practiceR').checked,ap=$('#practiceA').checked,g=$('#practiceG').checked,ev=$('#practiceEvidence').value.trim();if(!r&&!ap&&!g)return toast('Choose an honest R, A or G assessment.');if(ap&&!ev)return toast('Record the independent application proof.');state.assessments[id]={r,a:ap,g};state.notes['practice-'+id]=$('#practiceAttempt').value+(ev?'\nApplication: '+ev:'');enroll(state,id,config.reviewIntervals);if(g){state.reviews[id].due=plusDays(dayKey(),1);state.reviews[id].guided=true;}if(ap)award(state,'application:'+id,30);state.activity[dayKey()]=true;save();close();render();celebrate('Assessment saved. Recall and application tracked separately.');break;}case'open-review':openReview(el.dataset.id);break;case'review-list':reviewSelection=null;render();break;case'reveal-review':if(!$('#recallAttempt').value.trim()&&!$('#spokenAttempt').checked)return toast('Try recalling before revealing the answer.');reviewAnswer=true;$('#referenceAnswer').hidden=false;el.textContent='Reference shown';break;case'grade-guided':recordGrade('G');break;case'grade-recalled':recordGrade('R');break;case'new-card':newCard();break;case'save-card':{const front=$('#cardFront').value.trim(),back=$('#cardBack').value.trim();if(!front||!back)return toast('Add a focused prompt and reference answer.');const id='custom-'+crypto.randomUUID();state.customCards.push({id,title:'Personal recall card',kind:'T',question:front,answer:back});rebuildMap();enroll(state,id,config.reviewIntervals);save();close();render();toast('Card created. First return is tomorrow.');break;}case'timer-toggle':toggleTimer();break;case'timer-reset':resetTimer();break;case'timer-mode':if(timer.running)return toast('Pause the current timer before changing mode.');resetTimer(el.dataset.mode);break;case'new-note':dialog('New study note','<label class="field">Title<input id="noteTitle" maxlength="100"></label><label class="field">Note<textarea id="noteBody"></textarea></label>',btn('Save note','save-note','primary'));break;case'save-note':{const title=$('#noteTitle').value.trim();if(!title)return toast('Give the note a title.');state.notes[title+' · '+crypto.randomUUID().slice(0,5)]=$('#noteBody').value;save();close();render();break;}case'remove-note':delete state.notes[el.dataset.key];save();render();break;case'edit-todo':{const t=state.todos.find(t=>t.id===el.dataset.id);dialog('Edit next action',`<label class="field">Next action<input id="editTodoText" maxlength="400" value="${esc(t.text)}"></label>`,btn('Save action','save-todo','primary',`data-id="${esc(t.id)}"`));break;}case'save-todo':{const text=$('#editTodoText').value.trim();if(!text)return toast('Keep one clear next action.');state.todos.find(t=>t.id===el.dataset.id).text=text;save();close();render();break;}case'remove-todo':state.todos=state.todos.filter(t=>t.id!==el.dataset.id);save();render();break;case'save-settings':{const n=Number($('#settingFocus').value),s=Number($('#settingShort').value),l=Number($('#settingLong').value),start=$('#settingStart').value;if(!Number.isInteger(n)||n<1||n>120||!Number.isInteger(s)||s<1||s>30||!Number.isInteger(l)||l<1||l>60)return toast('Choose focus 1–120, short break 1–30 and long break 1–60 whole minutes.');if(start&&new Date(start+'T12:00:00').getDay()!==1)return toast('Choose a Monday for Day 1.');Object.assign(state.settings,{name:$('#settingName').value.trim()||'Learner',sound:$('#settingSound').checked,volume:Number($('#settingVolume').value),reducedMotion:$('#settingMotion').checked,focus:n,shortBreak:s,longBreak:l,startDate:start});captureAnki();save();if(!timer.running){timer.remaining=timer.total=timerLength(timer.mode);saveTimer();}toast('Preferences saved.');break;}case'test-sound':state.settings.sound=true;if($('#settingVolume'))state.settings.volume=Number($('#settingVolume').value);save();await playSound();break;case'upload-sound':{const file=await readFile('audio/*');if(!file)break;if(file.size>2000000||!file.type.startsWith('audio/'))throw Error('Choose an audio file under 2 MB.');state.settings.customAudio=await new Promise((res,rej)=>{const fr=new FileReader();fr.onload=()=>res(fr.result);fr.onerror=rej;fr.readAsDataURL(file);});save();render();await playSound();break;}case'default-sound':delete state.settings.customAudio;save();render();break;case'backup':download('Recall_Forge_Backup_'+dayKey()+'.json',JSON.stringify(state,null,2));toast('Backup exported. Keep it somewhere durable.');break;case'erase-progress':eraseProgressDialog();break;case'confirm-erase-progress':confirmEraseProgress();break;case'restore':{const file=await readFile('.json');if(!file)break;if(file.size>10000000)throw Error('Backup must be under 10 MB.');const pending=validateBackup(JSON.parse(await file.text()));window.pendingBackup=pending;dialog('Restore this backup?',`<p>Backup: ${Object.keys(pending.tasks).length} day records, ${pending.reviewLog.length} review attempts and ${pending.customTracks.length} custom tracks.</p><p>This replaces progress in this browser. A copy of your current progress will be downloaded first.</p>`,btn('Cancel','close')+btn('Export current & restore','confirm-restore','primary'));break;}case'confirm-restore':download('Recall_Forge_Before_Restore.json',JSON.stringify(state,null,2));state=window.pendingBackup;delete window.pendingBackup;timer={...timer,running:false,remaining:state.settings.focus*60,total:state.settings.focus*60};saveTimer();save();rebuildMap();close();render();toast('Backup restored.');break;case'audit':audit();break;case'anki-help':ankiHelp();break;case'anki-connect':await connectAnki();break;case'send-anki':await sendAnki();break;case'export-tsv':exportTSV();break;case'anki-create-deck':captureAnki();dialog('Create an Anki deck','<label class="field">Deck name<input id="newDeckName" placeholder="Recall Forge"></label>',btn('Create in Anki','confirm-anki-deck','primary'));break;case'confirm-anki-deck':{const name=$('#newDeckName').value.trim();if(!name)return toast('Enter a deck name.');await callAnki('createDeck',{deck:name});state.settings.ankiDeck=name;ankiDecks=await callAnki('deckNames');save();close();render();toast('Deck created in Anki.');break;}case'anki-due':captureAnki();{const cards=await callAnki('findCards',{query:`deck:"${state.settings.ankiDeck.replace(/["\\]/g,'')}" is:due`});ankiStatus=`${cards.length} due cards in ${state.settings.ankiDeck} (Anki schedule)`;render();break;}case'anki-review':captureAnki();await callAnki('guiDeckReview',{name:state.settings.ankiDeck});toast('Opened the deck in desktop Anki. Review there to use Anki scheduling.');break;case'flow-practice':{const f=config.flows[Number(el.dataset.index)];dialog(f.title,`<p>${esc(f.detail)}</p><p>Trace one real payment through this boundary. Name the operation identity, durable state and what happens if the process crashes immediately after this step.</p><textarea data-note="flow-${el.dataset.index}" placeholder="Your explanation and a concrete failure trace…">${esc(state.notes['flow-'+el.dataset.index]||'')}</textarea><p>Saved as you type. Use your own architecture and state its assumptions.</p>`);break;}}
}catch(error){toast(error.name==='AbortError'?'Connection timed out. Check Anki and browser access settings; TSV export remains available.':error.message);}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='quickQuery')$('#quickResults').innerHTML=quickResults(el.value);if(el.dataset.note){state.notes[el.dataset.note]=el.value;save();}if(el.id==='timerGoal'){timer.goal=el.value;saveTimer();}if(el.id==='bankSearch'||el.id==='trackSearch'){query=el.value;const pos=el.selectionStart;const id=el.id;render();const next=$('#'+id);next.focus();next.setSelectionRange(pos,pos);}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='daySelect'){state.currentDay=Number(el.value);save();render();}if(el.id==='bankFilter'){filter=el.value;render();}if(el.classList.contains('anki-select')){el.checked?chosen.add(el.dataset.id):chosen.delete(el.dataset.id);const scroll=window.scrollY;render();window.scrollTo(0,scroll);}if(el.classList.contains('todo-check')){const t=state.todos.find(t=>t.id===el.dataset.id);t.done=el.checked;save();render();if(t.done)celebrate('Next action completed.');}if(el.id==='ankiDeck'){state.settings.ankiDeck=el.value;save();}});
document.addEventListener('submit',e=>{if(e.target.id==='todoForm'){e.preventDefault();const text=$('#todoText').value.trim();if(!text)return;state.todos.push({id:crypto.randomUUID(),text,done:false});save();render();}});
$('#quickSearch').onclick=quickSearch;$('#reviewBell').onclick=()=>navigate('reviews');document.addEventListener('keydown',e=>{const editing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);if((e.key==='k'&&(e.ctrlKey||e.metaKey))||(e.key==='/'&&!editing&&!$('#modal').open)){e.preventDefault();quickSearch();}});
$('#soundToggle').onclick=()=>{state.settings.sound=!state.settings.sound;save();toast(state.settings.sound?'Completion sound on':'Completion sound off');};$('#themeToggle').onclick=()=>{state.settings.theme=state.settings.theme==='dark'?'light':'dark';save();};$('#menuButton').onclick=()=>document.body.classList.toggle('nav-open');$('#helpButton').onclick=()=>navigate('method');
window.addEventListener('hashchange',()=>{if(config)navigate(location.hash.slice(1)||'today');});
$('#date').textContent=new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'});
try{const r=await fetch('curriculum.json');if(!r.ok)throw Error('Curriculum could not load.');config=await r.json();if(config.days.length!==154)throw Error('The plan must contain 154 days.');rebuildMap();view=location.hash.slice(1)||'today';render();}catch(e){$('#main').innerHTML=`<div class="empty-state">${esc(e.message)} Reload to retry. Your local progress has not been deleted.</div>`;}
